//! The 3D scene pass for the Phase 2 primitive (plan section 8, "3D
//! layers"; section 26 Phase 2; amendment 11).
//!
//! A 3D object layer renders as the legacy compositor renders it
//! (`compositor.ts`, the `layer3d` branch; `core/scene3d/service.ts` and
//! `runtime.ts`): the composition's evaluated scene (`pm-eval`'s
//! `compositionScene`), the object at its `world3D` matrix, the camera at its
//! world pose aimed at its target, three.js r180's `MeshStandardMaterial`
//! program (generated by [`crate::three::program`] byte for byte, compiled
//! through `pm_gpu::glsl`), a hemisphere ambient light, directional (sun)
//! lights, ACES Filmic with r180's `exposure / 0.6`, sRGB output encoding E,
//! 4× MSAA into an RGBA8 target, the shared depth prepass followed by the
//! layer's color pass, and the scene background cleared on the bottom layer
//! of the depth set. The resolved, premultiplied 8-bit output is drawn into
//! the 2D graph as a screen-space quad with the layer's opacity.
//!
//! What this pass does not draw yet (shadows, point, spot, and area lights,
//! textures, transparency, imported models, more than one object per
//! composition, ...) is listed by [`check`] and routed to the legacy engine
//! (section 21's capability routing).

use std::collections::HashMap;
use std::sync::Arc;

use pm_eval::node;
use pm_eval::parenting::Role3d;
use pm_eval::{JsResult, Scope};
use pm_geom3d::{Geometry, Parameters, Primitive};
use pm_gpu::glsl::{self, ScalarKind};
use pm_gpu::{Target, TargetPool};
use pm_model::json::{Map, Value};
use pm_model::{JsString, Node, NodeKind};

use crate::js;
use crate::three::math::{self, Mat4, Vec3};
use crate::three::program::{Parameters as ProgramParameters, sources, standard_material};

/// The MSAA sample count of the output canvas (`antialias: true`; ANGLE on
/// Metal allocates 4 samples, recorded by `tools/three-ref`).
pub const SAMPLES: u32 = 4;

/// Primitives the pass draws (three.js geometry, `pm_geom3d`).
pub const PRIMITIVES: [&str; 6] = ["box", "sphere", "plane", "cylinder", "cone", "torus"];

/// The camera of the pass.
#[derive(Debug, Clone, PartialEq)]
pub struct Camera3d {
    /// `matrixWorld` after `lookAt` (through a quaternion, as three.js).
    pub world: Mat4,
    pub orthographic: bool,
    /// Degrees, clamped to 1..150.
    pub fov: f64,
    pub zoom: f64,
    pub near: f64,
    pub far: f64,
}

/// A directional light.
#[derive(Debug, Clone, PartialEq)]
pub struct Sun {
    pub position: Vec3,
    pub target: Vec3,
    /// Linear color (`Color.set(hex)`).
    pub color: Vec3,
    pub intensity: f64,
}

/// The material (`MeshStandardMaterial` as `sync` configures it).
#[derive(Debug, Clone, PartialEq)]
pub struct Material3d {
    /// `material.name` (`SHADER_NAME`).
    pub name: String,
    pub color: Vec3,
    pub roughness: f64,
    pub metalness: f64,
    pub emissive: Vec3,
    pub emissive_intensity: f64,
    pub double_sided: bool,
}

/// One 3D object layer's render.
#[derive(Debug, Clone, PartialEq)]
pub struct Object3dPlan {
    pub layer: String,
    /// Output size of the pass (the target the layer draws into).
    pub width: u32,
    pub height: u32,
    pub primitive: Primitive,
    /// `matrixWorld` (`world3D`).
    pub model: Mat4,
    pub material: Material3d,
    /// The prepass writes depth (layer opacity ≥ 0.999, no enabled mask).
    pub depth_write: bool,
    pub camera: Camera3d,
    pub exposure: f64,
    /// Hemisphere light: linear sky color, ground color (0.35 × sky), intensity.
    pub hemisphere: (Vec3, Vec3, f64),
    /// Visible directional lights in scene order.
    pub suns: Vec<Sun>,
    /// The clear color of the bottom layer of the depth set: the background
    /// hex as linear components (`Color`), or `None` for transparency.
    pub background: Option<Vec3>,
}

/// A static capability issue: the layer (when one is at fault) and why.
pub(crate) type Issue = (Option<String>, String);

fn str_member(n: Option<&Node>, key: &str) -> Option<String> {
    node::string(node::member(n, key)).map(JsString::to_string_lossy)
}

fn is_static_value(prop: Option<&Node>, accept: impl Fn(&Node) -> bool) -> bool {
    match prop {
        None => true,
        Some(p) => {
            let kf = node::array(node::member(Some(p), "kf")).is_some_and(|k| !k.is_empty());
            let expr = node::member(Some(p), "expr").is_some_and(|e| node::truthy(Some(e)));
            match p.kind() {
                NodeKind::Object(_) => {
                    !kf && !expr && node::member(Some(p), "v").is_some_and(&accept)
                }
                _ => accept(p),
            }
        }
    }
}

fn object_is_empty(n: Option<&Node>) -> bool {
    match n.map(Node::kind) {
        None | Some(NodeKind::Null) => true,
        Some(NodeKind::Object(m)) => m.is_empty(),
        Some(NodeKind::Array(a)) => a.is_empty(),
        _ => false,
    }
}

/// Whether a layer is on for the whole composition: `on` not false, no
/// group above it, and its time range covering `[0, dur]`.
fn always_active(layer: &Node, comp: &Node) -> bool {
    if matches!(
        node::member(Some(layer), "on").map(Node::kind),
        Some(NodeKind::Bool(false))
    ) {
        return false;
    }
    if node::truthy(node::member(Some(layer), "group")) {
        return false;
    }
    let from = node::to_number(node::member(Some(layer), "from"));
    let dur = node::to_number(node::member(Some(layer), "dur"));
    let comp_dur = node::to_number(node::member(Some(comp), "dur"));
    from <= 0.0 && from + dur >= comp_dur && comp_dur.is_finite()
}

/// Static checks of a composition's 3D layers against what this pass draws
/// (conservative: anything that could need more at some time is listed).
pub(crate) fn check(_root: &Node, comp: &Node, layers: &[Node], objects: usize) -> Vec<Issue> {
    let mut out = Vec::new();
    let id = js::layer_id;
    if objects > 1 {
        out.push((
            None,
            "more than one 3D object layer in a composition (shared depth sets)".to_owned(),
        ));
    }
    // Shadows: a casting light (the studio sun casts when no light layer
    // is active) with the environment's shadows on (the studio environment
    // has them on when no camera layer is active).
    let lights: Vec<&Node> = layers
        .iter()
        .filter(|l| Role3d::of(l) == Some(Role3d::Light))
        .collect();
    let cameras: Vec<&Node> = layers
        .iter()
        .filter(|l| Role3d::of(l) == Some(Role3d::Camera))
        .collect();
    let member = |l: &Node, path: &[&str]| -> Option<String> {
        let mut n = node::member(Some(l), "d");
        n = node::member(n, "data");
        for (i, k) in path.iter().enumerate() {
            if i + 1 == path.len() {
                return str_member(n, k);
            }
            n = node::member(n, k);
        }
        None
    };
    let flag_not_false = |n: Option<&Node>| !matches!(n.map(Node::kind), Some(NodeKind::Bool(false)));
    let default_sun = lights.is_empty() || !lights.iter().any(|l| always_active(l, comp));
    let any_casting_light = default_sun
        || lights.iter().any(|l| {
            let light = node::member(node::member(node::member(Some(l), "d"), "data"), "light");
            flag_not_false(node::member(light, "castShadow"))
        });
    let default_environment = cameras.is_empty() || !cameras.iter().any(|c| always_active(c, comp));
    let any_shadow_environment = default_environment
        || cameras.iter().any(|c| {
            let env = node::member(
                node::member(node::member(Some(c), "d"), "data"),
                "environment",
            );
            flag_not_false(node::member(env, "shadows"))
        });
    if any_casting_light && any_shadow_environment {
        out.push((None, "shadows (a casting light with environment shadows on)".to_owned()));
    }
    for l in &lights {
        let ty = member(l, &["light", "type"]).unwrap_or_else(|| "sun".to_owned());
        if ty != "sun" {
            out.push((Some(id(l)), format!("{ty} lights")));
        }
    }
    for l in layers.iter().filter(|l| Role3d::of(l) == Some(Role3d::Object)) {
        let object = node::member(node::member(node::member(Some(l), "d"), "data"), "object");
        let source = node::member(object, "source");
        match str_member(source, "primitive") {
            Some(p) if PRIMITIVES.contains(&p.as_str()) => {}
            Some(p) => out.push((Some(id(l)), format!("{p} primitives"))),
            None => {
                let kind = if node::member(source, "assetId").is_some() {
                    "imported models"
                } else if node::member(source, "mesh").is_some() {
                    "mesh sources"
                } else if node::member(source, "lathe").is_some() {
                    "lathe sources"
                } else if node::member(source, "extrude").is_some() {
                    "extrude sources"
                } else {
                    "an unknown 3D source"
                };
                out.push((Some(id(l)), kind.to_owned()));
            }
        }
        let material = node::member(object, "material");
        if !object_is_empty(node::member(material, "maps")) {
            out.push((Some(id(l)), "material texture maps".to_owned()));
        }
        if !object_is_empty(node::member(material, "shader")) {
            out.push((Some(id(l)), "node materials (shader previews)".to_owned()));
        }
        if !object_is_empty(node::member(object, "slots")) {
            out.push((Some(id(l)), "material slots".to_owned()));
        }
        if node::truthy(node::member(object, "useSourceMaterials")) {
            out.push((Some(id(l)), "source materials".to_owned()));
        }
        if node::truthy(node::member(object, "generation")) {
            out.push((Some(id(l)), "model-group recipe parts".to_owned()));
        }
        let opacity = node::member(node::member(material, "p"), "opacity");
        if !is_static_value(opacity, |v| node::to_number(Some(v)) >= 1.0) {
            out.push((Some(id(l)), "transparent materials".to_owned()));
        }
    }
    out
}

fn value_of(v: Option<&Value>) -> Option<&Value> {
    match v {
        Some(Value::Object(m)) if m.contains_key("v") => m.get("v"),
        other => other,
    }
}

fn num(map: &Map, key: &str) -> Option<f64> {
    match value_of(map.get(key)) {
        Some(Value::Number(n)) => Some(*n),
        _ => None,
    }
}

fn text(map: &Map, key: &str) -> Option<String> {
    match value_of(map.get(key)) {
        Some(Value::String(s)) => Some(s.to_string_lossy()),
        _ => None,
    }
}

fn boolean(map: &Map, key: &str) -> Option<bool> {
    match value_of(map.get(key)) {
        Some(Value::Bool(b)) => Some(*b),
        _ => None,
    }
}

fn obj<'a>(map: &'a Map, key: &str) -> Option<&'a Map> {
    match map.get(key) {
        Some(Value::Object(m)) => Some(m),
        _ => None,
    }
}

fn arr<'a>(map: &'a Map, key: &str) -> &'a [Value] {
    match map.get(key) {
        Some(Value::Array(a)) => a,
        _ => &[],
    }
}

fn color(map: &Map, key: &str) -> Result<Vec3, String> {
    let s = text(map, key).ok_or_else(|| format!("3D color {key} missing"))?;
    math::color_hex(&s).ok_or_else(|| format!("3D color {key} {s:?} is not #RRGGBB"))
}

/// `JS max(a, b)`.
fn jmax(a: f64, b: f64) -> f64 {
    js::max(a, b)
}

/// The pass for one object layer at `time`, into a `width` × `height`
/// target; `Ok(Err(reason))` when the frame needs something this pass does
/// not draw.
pub(crate) fn plan_object<'d>(
    scope: &mut Scope<'_, 'd>,
    layer: &'d Node,
    time: f64,
    width: u32,
    height: u32,
) -> JsResult<Result<Object3dPlan, String>> {
    let evaluated = scope.composition_scene(time)?;
    let Value::Object(scene) = &evaluated.scene else {
        return Ok(Err("the evaluated 3D scene".to_owned()));
    };
    let layer_id = js::layer_id(layer);
    let objects = arr(scene, "objects");
    if objects.len() > 1 {
        return Ok(Err(
            "more than one 3D object layer in a composition (shared depth sets)".to_owned(),
        ));
    }
    let Some(Value::Object(object)) = objects.first() else {
        return Ok(Err("the 3D object is not in the evaluated scene".to_owned()));
    };
    if text(object, "id").as_deref() != Some(layer_id.as_str()) {
        return Ok(Err("the 3D object is not in the evaluated scene".to_owned()));
    }
    if !evaluated.recipe_parts.is_empty() {
        return Ok(Err("model-group recipe parts".to_owned()));
    }
    // Geometry.
    let Some(source) = obj(object, "source") else {
        return Ok(Err("an unknown 3D source".to_owned()));
    };
    let Some(name) = text(source, "primitive") else {
        return Ok(Err("a 3D source that is not a primitive".to_owned()));
    };
    let p = obj(source, "parameters");
    let param = |k: &str| p.and_then(|p| num(p, k));
    let parameters = Parameters {
        width: param("width"),
        height: param("height"),
        depth: param("depth"),
        radius: param("radius"),
        radius_top: param("radiusTop"),
        radius_bottom: param("radiusBottom"),
        tube: param("tube"),
        segments: param("segments"),
        detail: param("detail"),
    };
    let Some(primitive) = Primitive::from_parameters(&name, &parameters) else {
        return Ok(Err(format!("{name} primitives")));
    };
    // Material (`materialPreview` without a shader is the definition itself).
    if boolean(object, "useSourceMaterials") == Some(true) {
        return Ok(Err("source materials".to_owned()));
    }
    if !arr(object, "slots").is_empty() {
        return Ok(Err("material slots".to_owned()));
    }
    let Some(material) = obj(object, "material") else {
        return Ok(Err("a 3D object without a material".to_owned()));
    };
    if obj(material, "maps").is_some_and(|m| !m.is_empty()) {
        return Ok(Err("material texture maps".to_owned()));
    }
    if material.get("shader").is_some_and(|s| !matches!(s, Value::Null)) {
        return Ok(Err("node materials (shader previews)".to_owned()));
    }
    let Some(mp) = obj(material, "p") else {
        return Ok(Err("a 3D material without values".to_owned()));
    };
    let opacity = num(mp, "opacity").unwrap_or(1.0);
    if opacity < 1.0 {
        return Ok(Err("transparent materials".to_owned()));
    }
    let material = match (|| -> Result<Material3d, String> {
        Ok(Material3d {
            name: "Surface".to_owned(),
            color: color(mp, "color")?,
            roughness: num(mp, "roughness").ok_or("roughness")?,
            metalness: num(mp, "metalness").ok_or("metalness")?,
            emissive: color(mp, "emissive")?,
            emissive_intensity: num(mp, "emissiveIntensity").ok_or("emissiveIntensity")?,
            double_sided: boolean(material, "doubleSided") != Some(false),
        })
    })() {
        Ok(m) => m,
        Err(e) => return Ok(Err(format!("3D material: {e}"))),
    };
    // Lights.
    let Some(environment) = obj(scene, "environment") else {
        return Ok(Err("the 3D environment".to_owned()));
    };
    let shadows = boolean(environment, "shadows") != Some(false);
    let mut suns = Vec::new();
    let mut shadow_lights = 0;
    for light in arr(scene, "lights") {
        let Value::Object(light) = light else { continue };
        let ty = text(light, "type").unwrap_or_else(|| "sun".to_owned());
        let lp = obj(light, "p").cloned().unwrap_or_default();
        let visible = boolean(&lp, "visible") != Some(false);
        // `castShadow = node.castShadow && shadows && shadowLights++ < 4`.
        let casts = boolean(light, "castShadow") != Some(false) && shadows && {
            let first_four = shadow_lights < 4;
            shadow_lights += 1;
            first_four
        };
        if !visible {
            continue;
        }
        if ty != "sun" {
            return Ok(Err(format!("{ty} lights")));
        }
        if casts {
            return Ok(Err("shadows (a casting light with environment shadows on)".to_owned()));
        }
        let lid = text(light, "id").unwrap_or_default();
        // A light layer is placed at its world position and aimed through its
        // parent space (`compositionRuntime`); the studio sun keeps its values.
        let placed = match scope
            .layers()
            .iter()
            .find(|l| Role3d::of(l) == Some(Role3d::Light) && js::layer_id(l) == lid)
        {
            Some(l) => scope.scene_light_aim(l, time)?,
            None => None,
        };
        let (position, target) = match placed {
            Some(p) => p,
            None => (
                [
                    num(&lp, "x").unwrap_or(0.0),
                    num(&lp, "y").unwrap_or(0.0),
                    num(&lp, "z").unwrap_or(0.0),
                ],
                [
                    num(&lp, "targetX").unwrap_or(0.0),
                    num(&lp, "targetY").unwrap_or(0.0),
                    num(&lp, "targetZ").unwrap_or(0.0),
                ],
            ),
        };
        let c = match color(&lp, "color") {
            Ok(c) => c,
            Err(e) => return Ok(Err(e)),
        };
        suns.push(Sun {
            position,
            target,
            color: c,
            intensity: num(&lp, "intensity").unwrap_or(3.0),
        });
    }
    // Camera.
    let Some(camera) = obj(scene, "camera") else {
        return Ok(Err("the 3D camera".to_owned()));
    };
    let cp = obj(camera, "p").cloned().unwrap_or_default();
    let orthographic = text(camera, "projection").as_deref() == Some("orthographic");
    let pose = scope.scene_camera(time)?;
    let near = jmax(0.0001, num(&cp, "near").unwrap_or(0.01));
    let far = jmax(near + 0.01, num(&cp, "far").unwrap_or(1000.0));
    let zoom = jmax(0.001, num(&cp, "zoom").unwrap_or(1.0));
    let fov = js::clamp(num(&cp, "fov").unwrap_or(45.0), 1.0, 150.0);
    let camera = Camera3d {
        world: math::camera_world(pose.position, pose.target, pose.up),
        orthographic,
        fov,
        zoom,
        near,
        far,
    };
    // Environment.
    let ep = obj(environment, "p").cloned().unwrap_or_default();
    let sky = match color(&ep, "ambientColor") {
        Ok(c) => c,
        Err(e) => return Ok(Err(e)),
    };
    let ground = [sky[0] * 0.35, sky[1] * 0.35, sky[2] * 0.35];
    let ambient = num(&ep, "ambient").unwrap_or(0.5);
    let exposure = num(&ep, "exposure").unwrap_or(1.0);
    let background = match environment.get("background") {
        Some(Value::String(s)) => match math::color_hex(&s.to_string_lossy()) {
            Some(c) => Some(c),
            None => return Ok(Err("a 3D background that is not #RRGGBB".to_owned())),
        },
        _ => None,
    };
    // The object: `world3D`, depth writes by layer opacity and masks.
    let model = scope.world3d(layer, time, false)?;
    let opacity = scope.world_opacity(layer, time)?;
    let depth_write = opacity >= 0.999;
    Ok(Ok(Object3dPlan {
        layer: layer_id,
        width,
        height,
        primitive,
        model,
        material,
        depth_write,
        camera,
        exposure,
        hemisphere: (sky, ground, ambient),
        suns,
        background,
    }))
}

/// Uniform values of the standard material's draw, by GL name, as three.js
/// sets them (`WebGLRenderer.setProgram`, `WebGLLights`, `WebGLMaterials`).
pub fn uniforms(plan: &Object3dPlan) -> Vec<(String, Vec<f64>)> {
    let aspect = f64::from(plan.width) / jmax(1.0, f64::from(plan.height));
    let c = &plan.camera;
    let projection = if c.orthographic {
        math::orthographic(aspect, c.zoom, c.near, c.far)
    } else {
        math::perspective(c.fov, aspect, c.zoom, c.near, c.far)
    };
    let view = math::invert(&c.world);
    let model_view = math::multiply(&view, &plan.model);
    let normal = math::normal_matrix(&model_view);
    let m = &plan.material;
    let mut u: Vec<(String, Vec<f64>)> = vec![
        ("modelMatrix".into(), plan.model.to_vec()),
        ("modelViewMatrix".into(), model_view.to_vec()),
        ("projectionMatrix".into(), projection.to_vec()),
        ("viewMatrix".into(), view.to_vec()),
        ("normalMatrix".into(), normal.to_vec()),
        (
            "cameraPosition".into(),
            vec![c.world[12], c.world[13], c.world[14]],
        ),
        ("isOrthographic".into(), vec![f64::from(u8::from(c.orthographic))]),
        ("diffuse".into(), m.color.to_vec()),
        ("opacity".into(), vec![1.0]),
        (
            "emissive".into(),
            m.emissive.iter().map(|v| v * m.emissive_intensity).collect(),
        ),
        ("roughness".into(), vec![m.roughness]),
        ("metalness".into(), vec![m.metalness]),
        ("toneMappingExposure".into(), vec![plan.exposure]),
        ("ambientLightColor".into(), vec![0.0; 3]),
        ("lightProbe".into(), vec![0.0; 27]),
        ("envMapIntensity".into(), vec![1.0]),
    ];
    let (sky, ground, intensity) = plan.hemisphere;
    u.push((
        "hemisphereLights[0].skyColor".into(),
        sky.iter().map(|v| v * intensity).collect(),
    ));
    u.push((
        "hemisphereLights[0].groundColor".into(),
        ground.iter().map(|v| v * intensity).collect(),
    ));
    u.push((
        "hemisphereLights[0].direction".into(),
        math::transform_direction([0.0, 1.0, 0.0], &view).to_vec(),
    ));
    for (i, s) in plan.suns.iter().enumerate() {
        let d = [
            s.position[0] - s.target[0],
            s.position[1] - s.target[1],
            s.position[2] - s.target[2],
        ];
        u.push((
            format!("directionalLights[{i}].direction"),
            math::transform_direction(d, &view).to_vec(),
        ));
        u.push((
            format!("directionalLights[{i}].color"),
            s.color.iter().map(|v| v * s.intensity).collect(),
        ));
    }
    u
}

/// The program parameters of a plan.
fn program_parameters(plan: &Object3dPlan) -> Result<ProgramParameters, String> {
    standard_material(
        &plan.material.name,
        plan.material.double_sided,
        1,
        plan.suns.len() as u32,
    )
}

/// The pass output: premultiplied 8-bit color (E codes) and, when asked,
/// linear view depth (`r32float`, +inf where nothing drew), both in GL row
/// order and the plan's size.
pub struct Rendered3d {
    pub color: Target,
    pub depth: Option<Target>,
}

struct Compiled {
    program: glsl::Program,
    vertex: wgpu::ShaderModule,
    fragment: wgpu::ShaderModule,
    layout: wgpu::BindGroupLayout,
    pipeline_layout: wgpu::PipelineLayout,
}

struct Mesh {
    buffers: HashMap<&'static str, wgpu::Buffer>,
    index: wgpu::Buffer,
    count: u32,
}

#[derive(Clone, Copy, PartialEq, Eq, Hash)]
struct PipelineKey {
    program: u64,
    color: bool,
    depth_write: bool,
    cull: Option<wgpu::Face>,
    front_face_cw: bool,
}

struct Attachments {
    width: u32,
    height: u32,
    color: wgpu::TextureView,
    depth: wgpu::TextureView,
}

/// The depth surface pipeline (linear view depth for the ID surface).
struct DepthSurface {
    pipeline: wgpu::RenderPipeline,
    layout: wgpu::BindGroupLayout,
}

const DEPTH_SURFACE_WGSL: &str = r#"
struct U {
    model_view: mat4x4<f32>,
    projection: mat4x4<f32>,
};
@group(0) @binding(0) var<uniform> u: U;
struct Out {
    @builtin(position) pos: vec4<f32>,
    @location(0) depth: f32,
};
@vertex
fn vs(@location(0) position: vec3<f32>) -> Out {
    let mv = u.model_view * vec4<f32>(position, 1.0);
    var p = u.projection * mv;
    // GL row order and depth range, as the color passes (pm_gpu::glsl::VERTEX_EPILOGUE).
    p.y = -p.y;
    p.z = (p.z + p.w) * 0.5;
    var o: Out;
    o.pos = p;
    o.depth = -mv.z;
    return o;
}
@fragment
fn fs(in: Out) -> @location(0) vec4<f32> {
    return vec4<f32>(in.depth, 0.0, 0.0, 0.0);
}
"#;

/// The 3D scene pass: compiled programs, pipelines, meshes, and MSAA
/// attachments, kept across frames.
#[derive(Default)]
pub struct Scene3dRenderer {
    programs: HashMap<u64, Arc<Compiled>>,
    pipelines: HashMap<PipelineKey, wgpu::RenderPipeline>,
    meshes: HashMap<u64, Arc<Mesh>>,
    attachments: Option<Attachments>,
    depth_surface: Option<DepthSurface>,
}

fn hash_of(parts: &[&[u8]]) -> u64 {
    use sha2::{Digest, Sha256};
    let mut h = Sha256::new();
    for p in parts {
        h.update((p.len() as u64).to_le_bytes());
        h.update(p);
    }
    let d = h.finalize();
    u64::from_le_bytes(d[..8].try_into().unwrap())
}

fn primitive_key(p: &Primitive) -> u64 {
    hash_of(&[format!("{p:?}").as_bytes()])
}

/// Writes one uniform into a default-block image (std140, from the
/// program's reflection). Unknown names are uniforms the compiler
/// eliminated.
fn write_uniform(program: &glsl::Program, block: &mut [u8], name: &str, values: &[f64]) {
    let base = name.strip_suffix("[0]").unwrap_or(name);
    let Some(slot) = program
        .uniforms
        .get(name)
        .or_else(|| program.uniforms.get(base))
    else {
        return;
    };
    let per = (slot.columns * slot.rows) as usize;
    let elements = (values.len() / per.max(1)).min(slot.count as usize);
    for e in 0..elements {
        for col in 0..slot.columns as usize {
            for row in 0..slot.rows as usize {
                let v = values[e * per + col * slot.rows as usize + row];
                let off = slot.offset as usize
                    + e * slot.array_stride as usize
                    + col * slot.column_stride as usize
                    + row * 4;
                let bytes = match slot.kind {
                    ScalarKind::Float => (v as f32).to_le_bytes(),
                    ScalarKind::Sint => (v as i32).to_le_bytes(),
                    ScalarKind::Uint => (v as u32).to_le_bytes(),
                    ScalarKind::Bool => u32::from(v != 0.0).to_le_bytes(),
                };
                if off + 4 <= block.len() {
                    block[off..off + 4].copy_from_slice(&bytes);
                }
            }
        }
    }
}

impl Scene3dRenderer {
    fn program(
        &mut self,
        device: &wgpu::Device,
        params: &ProgramParameters,
    ) -> Result<(u64, Arc<Compiled>), String> {
        let (vs, fs) = sources(params)?;
        let key = hash_of(&[vs.as_bytes(), fs.as_bytes()]);
        if let Some(c) = self.programs.get(&key) {
            return Ok((key, c.clone()));
        }
        let program = glsl::compile(&vs, &fs).map_err(|e| format!("3D program: {e}"))?;
        if !program.textures.is_empty() {
            return Err("3D program samples textures this pass does not bind".to_owned());
        }
        let module = |m: &glsl::naga::Module, label: &str| {
            device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some(label),
                source: wgpu::ShaderSource::Naga(std::borrow::Cow::Owned(m.clone())),
            })
        };
        let vertex = module(&program.vertex, "three vs");
        let fragment = module(&program.fragment, "three fs");
        let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
            label: Some("three program"),
            entries: &[wgpu::BindGroupLayoutEntry {
                binding: glsl::DEFAULT_BLOCK_BINDING,
                visibility: wgpu::ShaderStages::VERTEX_FRAGMENT,
                ty: wgpu::BindingType::Buffer {
                    ty: wgpu::BufferBindingType::Uniform,
                    has_dynamic_offset: false,
                    min_binding_size: wgpu::BufferSize::new(u64::from(program.block_size)),
                },
                count: None,
            }],
        });
        let pipeline_layout = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
            label: Some("three program"),
            bind_group_layouts: &[Some(&layout)],
            immediate_size: 0,
        });
        let c = Arc::new(Compiled {
            program,
            vertex,
            fragment,
            layout,
            pipeline_layout,
        });
        self.programs.insert(key, c.clone());
        Ok((key, c))
    }

    fn mesh(&mut self, device: &wgpu::Device, p: &Primitive) -> Arc<Mesh> {
        let key = primitive_key(p);
        if let Some(m) = self.meshes.get(&key) {
            return m.clone();
        }
        let g: Geometry = p.geometry();
        let buffer = |label: &str, bytes: Vec<u8>, usage: wgpu::BufferUsages| {
            let mut bytes = bytes;
            // naga's MSL vertex pulling admits element i only when
            // i < bound size / stride (S7 finding 6); padding keeps GL's rule.
            bytes.resize(bytes.len() + 256, 0);
            wgpu::util::DeviceExt::create_buffer_init(
                device,
                &wgpu::util::BufferInitDescriptor {
                    label: Some(label),
                    contents: &bytes,
                    usage,
                },
            )
        };
        let f = |v: &[f32]| v.iter().flat_map(|x| x.to_le_bytes()).collect::<Vec<u8>>();
        let mut buffers = HashMap::new();
        buffers.insert(
            "position",
            buffer("3d position", f(&g.positions), wgpu::BufferUsages::VERTEX),
        );
        buffers.insert(
            "normal",
            buffer("3d normal", f(&g.normals), wgpu::BufferUsages::VERTEX),
        );
        buffers.insert("uv", buffer("3d uv", f(&g.uvs), wgpu::BufferUsages::VERTEX));
        let index = buffer(
            "3d index",
            g.indices.iter().flat_map(|i| i.to_le_bytes()).collect(),
            wgpu::BufferUsages::INDEX,
        );
        let m = Arc::new(Mesh {
            buffers,
            index,
            count: g.indices.len() as u32,
        });
        self.meshes.insert(key, m.clone());
        m
    }

    fn attachments(&mut self, device: &wgpu::Device, width: u32, height: u32) -> &Attachments {
        if !matches!(&self.attachments, Some(a) if a.width == width && a.height == height) {
            let make = |format: wgpu::TextureFormat, label: &str| {
                device
                    .create_texture(&wgpu::TextureDescriptor {
                        label: Some(label),
                        size: wgpu::Extent3d {
                            width,
                            height,
                            depth_or_array_layers: 1,
                        },
                        mip_level_count: 1,
                        sample_count: SAMPLES,
                        dimension: wgpu::TextureDimension::D2,
                        format,
                        usage: wgpu::TextureUsages::RENDER_ATTACHMENT,
                        view_formats: &[],
                    })
                    .create_view(&wgpu::TextureViewDescriptor::default())
            };
            self.attachments = Some(Attachments {
                width,
                height,
                color: make(wgpu::TextureFormat::Rgba8Unorm, "3d msaa color"),
                depth: make(wgpu::TextureFormat::Depth32Float, "3d msaa depth"),
            });
        }
        self.attachments.as_ref().unwrap()
    }

    fn pipeline(
        &mut self,
        device: &wgpu::Device,
        key: PipelineKey,
        compiled: &Compiled,
    ) -> wgpu::RenderPipeline {
        if let Some(p) = self.pipelines.get(&key) {
            return p.clone();
        }
        let mut inputs: Vec<(u32, &str)> = Vec::new();
        for name in ["position", "normal", "uv"] {
            if let Some(a) = compiled.program.attributes.get(name) {
                inputs.push((a.location, name));
            }
        }
        let formats = |name: &str| match name {
            "uv" => (wgpu::VertexFormat::Float32x2, 8),
            _ => (wgpu::VertexFormat::Float32x3, 12),
        };
        let attrs: Vec<[wgpu::VertexAttribute; 1]> = inputs
            .iter()
            .map(|(loc, name)| {
                [wgpu::VertexAttribute {
                    format: formats(name).0,
                    offset: 0,
                    shader_location: *loc,
                }]
            })
            .collect();
        let layouts: Vec<Option<wgpu::VertexBufferLayout>> = inputs
            .iter()
            .zip(attrs.iter())
            .map(|((_, name), a)| {
                Some(wgpu::VertexBufferLayout {
                    array_stride: formats(name).1,
                    step_mode: wgpu::VertexStepMode::Vertex,
                    attributes: a,
                })
            })
            .collect();
        // Clip y is negated (GL row order), so GL's counter-clockwise front
        // faces are clockwise here.
        let front_face = if key.front_face_cw {
            wgpu::FrontFace::Ccw
        } else {
            wgpu::FrontFace::Cw
        };
        let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
            label: Some(if key.color { "three color" } else { "three depth" }),
            layout: Some(&compiled.pipeline_layout),
            vertex: wgpu::VertexState {
                module: &compiled.vertex,
                entry_point: None,
                compilation_options: Default::default(),
                buffers: &layouts,
            },
            primitive: wgpu::PrimitiveState {
                topology: wgpu::PrimitiveTopology::TriangleList,
                strip_index_format: None,
                front_face,
                cull_mode: key.cull,
                unclipped_depth: false,
                polygon_mode: wgpu::PolygonMode::Fill,
                conservative: false,
            },
            depth_stencil: Some(wgpu::DepthStencilState {
                format: wgpu::TextureFormat::Depth32Float,
                depth_write_enabled: Some(key.depth_write),
                depth_compare: Some(wgpu::CompareFunction::LessEqual),
                stencil: Default::default(),
                bias: Default::default(),
            }),
            multisample: wgpu::MultisampleState {
                count: SAMPLES,
                mask: !0,
                alpha_to_coverage_enabled: false,
            },
            fragment: Some(wgpu::FragmentState {
                module: &compiled.fragment,
                entry_point: None,
                compilation_options: Default::default(),
                targets: &[Some(wgpu::ColorTargetState {
                    format: wgpu::TextureFormat::Rgba8Unorm,
                    // Opaque materials draw with NoBlending.
                    blend: None,
                    write_mask: if key.color {
                        wgpu::ColorWrites::ALL
                    } else {
                        wgpu::ColorWrites::empty()
                    },
                })],
            }),
            multiview_mask: None,
            cache: None,
        });
        self.pipelines.insert(key, pipeline.clone());
        pipeline
    }

    fn depth_surface(&mut self, device: &wgpu::Device) -> &DepthSurface {
        if self.depth_surface.is_none() {
            let module = device.create_shader_module(wgpu::ShaderModuleDescriptor {
                label: Some("3d depth surface"),
                source: wgpu::ShaderSource::Wgsl(DEPTH_SURFACE_WGSL.into()),
            });
            let layout = device.create_bind_group_layout(&wgpu::BindGroupLayoutDescriptor {
                label: Some("3d depth surface"),
                entries: &[wgpu::BindGroupLayoutEntry {
                    binding: 0,
                    visibility: wgpu::ShaderStages::VERTEX,
                    ty: wgpu::BindingType::Buffer {
                        ty: wgpu::BufferBindingType::Uniform,
                        has_dynamic_offset: false,
                        min_binding_size: wgpu::BufferSize::new(128),
                    },
                    count: None,
                }],
            });
            let pl = device.create_pipeline_layout(&wgpu::PipelineLayoutDescriptor {
                label: Some("3d depth surface"),
                bind_group_layouts: &[Some(&layout)],
                immediate_size: 0,
            });
            let pipeline = device.create_render_pipeline(&wgpu::RenderPipelineDescriptor {
                label: Some("3d depth surface"),
                layout: Some(&pl),
                vertex: wgpu::VertexState {
                    module: &module,
                    entry_point: Some("vs"),
                    compilation_options: Default::default(),
                    buffers: &[Some(wgpu::VertexBufferLayout {
                        array_stride: 12,
                        step_mode: wgpu::VertexStepMode::Vertex,
                        attributes: &[wgpu::VertexAttribute {
                            format: wgpu::VertexFormat::Float32x3,
                            offset: 0,
                            shader_location: 0,
                        }],
                    })],
                },
                primitive: wgpu::PrimitiveState::default(),
                depth_stencil: Some(wgpu::DepthStencilState {
                    format: wgpu::TextureFormat::Depth32Float,
                    depth_write_enabled: Some(true),
                    depth_compare: Some(wgpu::CompareFunction::Less),
                    stencil: Default::default(),
                    bias: Default::default(),
                }),
                multisample: wgpu::MultisampleState::default(),
                fragment: Some(wgpu::FragmentState {
                    module: &module,
                    entry_point: Some("fs"),
                    compilation_options: Default::default(),
                    targets: &[Some(wgpu::ColorTargetState {
                        format: wgpu::TextureFormat::R32Float,
                        blend: None,
                        write_mask: wgpu::ColorWrites::ALL,
                    })],
                }),
                multiview_mask: None,
                cache: None,
            });
            self.depth_surface = Some(DepthSurface { pipeline, layout });
        }
        self.depth_surface.as_ref().unwrap()
    }

    /// Records the pass for `plan` into `encoder`: the depth prepass, the
    /// color pass with MSAA resolve, and (with `depth_surface`) the linear
    /// view depth. Targets come from `pool`; the caller returns them after
    /// the frame is submitted.
    pub fn render(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        pool: &mut TargetPool,
        plan: &Object3dPlan,
        depth_surface: bool,
    ) -> Result<Rendered3d, String> {
        let (w, h) = (plan.width.clamp(1, 8192), plan.height.clamp(1, 8192));
        let params = program_parameters(plan)?;
        let (program_key, compiled) = self.program(device, &params)?;
        let mesh = self.mesh(device, &plan.primitive);
        // Uniform block.
        let mut block = vec![0u8; compiled.program.block_size as usize];
        let values = uniforms(plan);
        for (name, v) in &values {
            write_uniform(&compiled.program, &mut block, name, v);
        }
        let ubuf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("three uniforms"),
            size: block.len().max(16) as u64,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        queue.write_buffer(&ubuf, 0, &block);
        let bind = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("three uniforms"),
            layout: &compiled.layout,
            entries: &[wgpu::BindGroupEntry {
                binding: glsl::DEFAULT_BLOCK_BINDING,
                resource: ubuf.as_entire_binding(),
            }],
        });
        // `state.setMaterial`: FrontSide culls back faces; a mirrored object
        // (negative determinant) flips the front face.
        let cull = if plan.material.double_sided {
            None
        } else {
            Some(wgpu::Face::Back)
        };
        let front_face_cw = math::determinant(&plan.model) < 0.0;
        let key = |color: bool, depth_write: bool| PipelineKey {
            program: program_key,
            color,
            depth_write,
            cull,
            front_face_cw,
        };
        let depth_pipeline = self.pipeline(device, key(false, plan.depth_write), &compiled);
        let color_pipeline = self.pipeline(device, key(true, false), &compiled);
        let resolve = pool.take(
            device,
            w,
            h,
            wgpu::TextureFormat::Rgba8Unorm,
            wgpu::TextureUsages::RENDER_ATTACHMENT
                | wgpu::TextureUsages::TEXTURE_BINDING
                | wgpu::TextureUsages::COPY_SRC,
        );
        let inputs: Vec<&wgpu::Buffer> = {
            let mut v: Vec<(u32, &wgpu::Buffer)> = ["position", "normal", "uv"]
                .iter()
                .filter_map(|n| {
                    compiled
                        .program
                        .attributes
                        .get(*n)
                        .map(|a| (a.location, &mesh.buffers[n]))
                })
                .collect();
            v.sort_by_key(|(l, _)| *l);
            v.into_iter().map(|(_, b)| b).collect()
        };
        let attachments = self.attachments(device, w, h);
        let draw = |pass: &mut wgpu::RenderPass<'_>, pipeline: &wgpu::RenderPipeline| {
            pass.set_pipeline(pipeline);
            pass.set_bind_group(0, &bind, &[]);
            for (i, b) in inputs.iter().enumerate() {
                pass.set_vertex_buffer(i as u32, b.slice(..));
            }
            pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
            pass.draw_indexed(0..mesh.count, 0, 0..1);
        };
        // Depth prepass (`autoClear`: color, depth cleared; no color writes).
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("3d depth prepass"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &attachments.color,
                    depth_slice: None,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color::TRANSPARENT),
                        store: wgpu::StoreOp::Discard,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &attachments.depth,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Store,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            draw(&mut pass, &depth_pipeline);
        }
        // Color pass: the color surface cleared to the background on the
        // bottom layer of the set (`setClearColor(bg, 1)` in sRGB,
        // premultiplied) or transparent; depth kept.
        let clear = match plan.background {
            Some(c) => wgpu::Color {
                r: math::linear_to_srgb(c[0]),
                g: math::linear_to_srgb(c[1]),
                b: math::linear_to_srgb(c[2]),
                a: 1.0,
            },
            None => wgpu::Color::TRANSPARENT,
        };
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("3d color"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &attachments.color,
                    depth_slice: None,
                    resolve_target: Some(&resolve.view),
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(clear),
                        store: wgpu::StoreOp::Discard,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &attachments.depth,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Load,
                        store: wgpu::StoreOp::Discard,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            draw(&mut pass, &color_pipeline);
        }
        let depth = if depth_surface {
            Some(self.render_depth_surface(device, queue, encoder, pool, plan, &values, &mesh)?)
        } else {
            None
        };
        Ok(Rendered3d {
            color: resolve,
            depth,
        })
    }

    #[allow(clippy::too_many_arguments)]
    fn render_depth_surface(
        &mut self,
        device: &wgpu::Device,
        queue: &wgpu::Queue,
        encoder: &mut wgpu::CommandEncoder,
        pool: &mut TargetPool,
        plan: &Object3dPlan,
        values: &[(String, Vec<f64>)],
        mesh: &Mesh,
    ) -> Result<Target, String> {
        let (w, h) = (plan.width.clamp(1, 8192), plan.height.clamp(1, 8192));
        let get = |n: &str| {
            values
                .iter()
                .find(|(k, _)| k == n)
                .map(|(_, v)| v.clone())
                .ok_or_else(|| format!("uniform {n}"))
        };
        let mut data = Vec::with_capacity(128);
        for v in get("modelViewMatrix")?.iter().chain(get("projectionMatrix")?.iter()) {
            data.extend_from_slice(&(*v as f32).to_le_bytes());
        }
        let surface = self.depth_surface(device);
        let ubuf = device.create_buffer(&wgpu::BufferDescriptor {
            label: Some("3d depth surface"),
            size: 128,
            usage: wgpu::BufferUsages::UNIFORM | wgpu::BufferUsages::COPY_DST,
            mapped_at_creation: false,
        });
        queue.write_buffer(&ubuf, 0, &data);
        let bind = device.create_bind_group(&wgpu::BindGroupDescriptor {
            label: Some("3d depth surface"),
            layout: &surface.layout,
            entries: &[wgpu::BindGroupEntry {
                binding: 0,
                resource: ubuf.as_entire_binding(),
            }],
        });
        let target = pool.take(
            device,
            w,
            h,
            wgpu::TextureFormat::R32Float,
            wgpu::TextureUsages::RENDER_ATTACHMENT
                | wgpu::TextureUsages::TEXTURE_BINDING
                | wgpu::TextureUsages::COPY_SRC,
        );
        let depth = pool.take(
            device,
            w,
            h,
            wgpu::TextureFormat::Depth32Float,
            wgpu::TextureUsages::RENDER_ATTACHMENT,
        );
        {
            let mut pass = encoder.begin_render_pass(&wgpu::RenderPassDescriptor {
                label: Some("3d depth surface"),
                color_attachments: &[Some(wgpu::RenderPassColorAttachment {
                    view: &target.view,
                    depth_slice: None,
                    resolve_target: None,
                    ops: wgpu::Operations {
                        load: wgpu::LoadOp::Clear(wgpu::Color {
                            r: f64::INFINITY,
                            g: 0.0,
                            b: 0.0,
                            a: 0.0,
                        }),
                        store: wgpu::StoreOp::Store,
                    },
                })],
                depth_stencil_attachment: Some(wgpu::RenderPassDepthStencilAttachment {
                    view: &depth.view,
                    depth_ops: Some(wgpu::Operations {
                        load: wgpu::LoadOp::Clear(1.0),
                        store: wgpu::StoreOp::Discard,
                    }),
                    stencil_ops: None,
                }),
                timestamp_writes: None,
                occlusion_query_set: None,
                multiview_mask: None,
            });
            pass.set_pipeline(&surface.pipeline);
            pass.set_bind_group(0, &bind, &[]);
            pass.set_vertex_buffer(0, mesh.buffers["position"].slice(..));
            pass.set_index_buffer(mesh.index.slice(..), wgpu::IndexFormat::Uint32);
            pass.draw_indexed(0..mesh.count, 0, 0..1);
        }
        pool.give(depth);
        Ok(target)
    }
}
